"""
Text Adventure Engine
---------------------
A simple text adventure game engine supporting rooms, items, inventory, two-word command parsing, and save/load features using JSON.
"""

import json
import os
from typing import Dict, List, Optional

class Item:
    """A class representing an item in the game."""
    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description

    def to_dict(self):
        return {"name": self.name, "description": self.description}

    @staticmethod
    def from_dict(data: dict):
        return Item(data["name"], data["description"])

class Room:
    """A class representing a room in the game world."""
    def __init__(self, name: str, description: str, exits: Dict[str, str], items: List[Item]):
        self.name = name
        self.description = description
        self.exits = exits    # e.g., {"north": "kitchen"}
        self.items = items

    def to_dict(self):
        return {
            "name": self.name,
            "description": self.description,
            "exits": self.exits,
            "items": [item.to_dict() for item in self.items]
        }

    @staticmethod
    def from_dict(data: dict):
        items = [Item.from_dict(i) for i in data["items"]]
        return Room(data["name"], data["description"], data["exits"], items)

class Game:
    """The main game engine."""
    def __init__(self, config_file: str):
        self.rooms: Dict[str, Room] = {}
        self.inventory: List[Item] = []
        self.current_room: Optional[str] = None
        self.config_file = config_file
        self.load_config(config_file)

    def load_config(self, filename):
        with open(filename, 'r') as f:
            data = json.load(f)
        # Load rooms
        self.rooms = {}
        for key, r in data["rooms"].items():
            self.rooms[key] = Room.from_dict(r)
        self.current_room = data["player"]["current_room"]
        self.inventory = [Item.from_dict(i) for i in data["player"]["inventory"]]

    def save_game(self, filename):
        data = {
            "rooms": {k: v.to_dict() for k,v in self.rooms.items()},
            "player": {
                "current_room": self.current_room,
                "inventory": [i.to_dict() for i in self.inventory]
            }
        }
        with open(filename, 'w') as f:
            json.dump(data, f, indent=2)
        print(f"Game saved to {filename}")

    def load_game(self, filename):
        self.load_config(filename)
        print(f"Game loaded from {filename}")

    def describe_current_room(self):
        room = self.rooms[self.current_room]
        desc = f"{room.name}\n{room.description}\nExits: {', '.join(room.exits.keys())}"
        if room.items:
            desc += "\nItems here: " + ', '.join(i.name for i in room.items)
        print(desc)
        return desc

    def move(self, direction):
        room = self.rooms[self.current_room]
        if direction in room.exits:
            self.current_room = room.exits[direction]
            print(f"You move {direction}.")
            self.describe_current_room()
        else:
            print("You can't go that way.")

    def take(self, item_name):
        room = self.rooms[self.current_room]
        for item in room.items:
            if item.name == item_name:
                self.inventory.append(item)
                room.items.remove(item)
                print(f"You take the {item_name}.")
                return
        print(f"There is no {item_name} here.")

    def drop(self, item_name):
        for item in self.inventory:
            if item.name == item_name:
                self.inventory.remove(item)
                self.rooms[self.current_room].items.append(item)
                print(f"You drop the {item_name}.")
                return
        print(f"You do not have a {item_name}.")

    def show_inventory(self):
        if self.inventory:
            print("Inventory: " + ', '.join(i.name for i in self.inventory))
        else:
            print("You have nothing.")

    def look(self, _=None):
        self.describe_current_room()

    def parse_command(self, command: str):
        words = command.strip().lower().split()
        if not words:
            return
        verb = words[0]
        noun = words[1] if len(words) > 1 else None

        actions = {
            "go": self.move,
            "move": self.move,
            "take": self.take,
            "get": self.take,
            "drop": self.drop,
            "inventory": (lambda _: self.show_inventory()),
            "inv": (lambda _: self.show_inventory()),
            "look": self.look,
            "save": (lambda _: self.save_game("save.json")),
            "load": (lambda _: self.load_game("save.json")),
            "quit": (lambda _: exit()),
        }
        if verb in actions:
            actions[verb](noun)
        else:
            print("I don't understand that command.")

def main():
    game = Game("config.json")
    print("Welcome to the Adventure Game!")
    game.describe_current_room()
    while True:
        command = input("> ")
        game.parse_command(command)

if __name__ == "__main__":
    main()
